import {googlePriceQuestion,googlePriceUrl,parseGooglePrices} from './google-pricing.js';
export function initGooglePricing({market,node,api,getData,validate,begin,current,onQuery,onUse,notify}){
 const status=market.querySelector('#research-status'),output=market.querySelector('#automatic-prices'),button=market.querySelector('#research'),fallback=node('div','google-response-import');fallback.hidden=true;const label=node('label','','Respuesta de Google'),textarea=node('textarea');textarea.rows=5;textarea.placeholder='Pega aquí la respuesta de Google con los tres precios y sus monedas.';label.append(textarea);const apply=node('button','','Mostrar los tres precios');apply.type='button';fallback.append(label,apply);output.after(fallback);textarea.addEventListener('input',e=>e.stopPropagation());let question='',generation=0;
 function render(scenarios,currency,url){output.replaceChildren();const grid=node('div','price-strategies');for(const scenario of scenarios){const card=node('article','price-strategy '+scenario.key),use=node('button','','Usar este precio');use.type='button';use.onclick=()=>onUse(scenario.price,currency);card.append(node('span','',scenario.label),node('strong','',(currency==='BOB'?'Bs ':'US$ ')+scenario.price.toLocaleString('en-US')),node('p','',scenario.reason),use);grid.append(card);}const source=node('a','','Ver consulta en Google ↗');source.href=url;source.target='_blank';source.rel='noopener noreferrer';output.append(grid,source);}
 button.onclick=async()=>{if(validate().length){notify('Corrige primero los datos de la ficha.',{type:'warning'});return;}const data=getData();if(!data.make||!data.name||!data.year){notify('Completa marca, modelo y año.',{type:'warning'});return;}generation=begin();onQuery();question=googlePriceQuestion(data);button.disabled=true;output.replaceChildren();fallback.hidden=true;textarea.value='';status.textContent='Preguntando a Google con los datos de este vehículo…';try{const result=await api('admin/research','POST',data);if(generation!==current()||question!==googlePriceQuestion(getData()))return;status.textContent=result.notice;if(result.valuation?.[0]?.scenarios?.length===3)render(result.valuation[0].scenarios,result.valuation[0].currency,result.googleUrl);else fallback.hidden=false;}catch{if(generation===current()){status.textContent='No se pudo recuperar la respuesta. Abre Preguntar a Google y pega su respuesta aquí.';fallback.hidden=false;}}finally{if(generation===current())button.disabled=false;}};
 apply.onclick=()=>{const data=getData();if(generation!==current()||question!==googlePriceQuestion(data)){notify('La ficha cambió. Vuelve a preguntar a Google.',{type:'warning'});return;}const currency=data.currency==='BOB'?'BOB':'USD',scenarios=parseGooglePrices(textarea.value,currency);if(!scenarios.length){notify('La respuesta debe incluir un importe único y su moneda para Venta rápida, Precio justo y Venta lenta, en ese orden de menor a mayor.',{type:'warning'});return;}render(scenarios,currency,googlePriceUrl(data));status.textContent='Tres precios extraídos de la respuesta de Google que pegaste. Revisa sus motivos antes de elegir.';fallback.hidden=true;};
 return{reset(){fallback.hidden=true;textarea.value='';question='';}};
}
